const MONO = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";

const eur = (n: any): string => (n === null || n === undefined ? "-" : "€" + Number(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const sgn0 = (n: any): string => (n === null || n === undefined ? "-" : (n >= 0 ? "+" : "-") + "€" + Math.abs(Number(n)).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const pct = (n: number): string => (n >= 0 ? "+" : "") + n.toFixed(2) + "%";
const pct0 = (n: number): string => (n >= 0 ? "+" : "") + n.toFixed(0) + "%";

function Mascot() {
  return (
    <svg viewBox="0 0 260 240" style={{ position: "absolute", left: "-14%", bottom: "-8%", width: "56%", height: "auto", zIndex: 1 }} aria-hidden="true">
      <defs>
        <radialGradient id="blob" cx="62%" cy="70%" r="75%">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="70%" stopColor="#f4f1ee" />
          <stop offset="100%" stopColor="#cfc8c2" />
        </radialGradient>
      </defs>
      <path d="M10 240 C 0 120 70 20 150 18 C 215 16 256 80 258 150 C 259 190 252 215 250 240 Z" fill="url(#blob)" />
      <path d="M50 150 C 52 128 84 122 92 142" fill="none" stroke="#000" strokeWidth="17" strokeLinecap="round" />
      <path d="M142 112 C 146 88 182 82 194 104" fill="none" stroke="#000" strokeWidth="17" strokeLinecap="round" />
    </svg>
  );
}

function Badge(props: { coin: string; size?: number }) {
  const s = props.size || 22;
  return (
    <span style={{ width: s + "px", height: s + "px", borderRadius: "9999px", background: COIN_COLOR[props.coin] || "#888", color: "#fff", fontWeight: 700, fontSize: Math.round(s * 0.5) + "px", display: "inline-flex", alignItems: "center", justifyContent: "center", flex: "none" }}>
      {props.coin.slice(0, 1)}
    </span>
  );
}

function Tile(props: { coin: string; side: string; big: number; pnl: number; note?: string; hi?: boolean }) {
  const good = props.big >= 0;
  return (
    <div style={{ background: good ? "#fff" : "#FDECEC", border: props.hi ? "2px solid #A9D9C0" : "2px solid transparent", borderLeft: "4px solid " + (COIN_COLOR[props.coin] || "#888"), borderRadius: "14px", padding: "10px 10px 9px 10px", minWidth: 0, boxShadow: "0 1px 2px rgba(0,0,0,0.06)" }}>
      <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
        <Badge coin={props.coin} size={20} />
        <span style={{ fontWeight: 800, fontSize: "13px", color: INK }}>{props.coin}</span>
        <span style={{ fontSize: "10px", color: MUTED }}>{props.side}</span>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginTop: "9px", gap: "4px", flexWrap: "wrap" }}>
        <span style={{ fontWeight: 800, fontSize: "19px", color: good ? GREEN : RED }}>{pct0(props.big)}</span>
        <span style={{ fontFamily: MONO, fontSize: "11px", fontWeight: 700, color: good ? INK : RED }}>{sgn0(props.pnl)}</span>
      </div>
      {props.note ? <div style={{ fontSize: "10px", color: MUTED, marginTop: "4px" }}>{props.note}</div> : null}
    </div>
  );
}

